export const getEpicChildIssuesQueryDocument = graphql(`
  query GetEpicChildIssues(
    $workspaceId: ID!
    $repositoryGhId: Int!
    $epicIssueNumber: Int!
  ) {
    issueByInfo(
      issueNumber: $epicIssueNumber
      repositoryGhId: $repositoryGhId
    ) {
      githubChildIssues {
        nodes {
          id
          number
          title
          body
          htmlUrl
          state
          assignees {
            nodes {
              id
              login
              # name
            }
          }
          blockingIssues {
            nodes {
              id
              number
            }
          }
          blockedIssues {
            nodes {
              id
              number
            }
          }
          pipelineIssue(workspaceId: $workspaceId) {
            id
            pipeline {
              id
              name
            }
          }
          estimate {
            value
          }
          sprints {
            nodes {
              id
              name
            }
          }
        }
      }
    }
  }
`);

export const getIssueByNumberQueryDocument = graphql(`
  query GetIssueByNumber(
    $workspaceId: ID!
    $repositoryGhId: Int!
    $issueNumber: Int!
  ) {
    issueByInfo(issueNumber: $issueNumber, repositoryGhId: $repositoryGhId) {
      id
      number
      title
      body
      htmlUrl
      state
      assignees {
        nodes {
          id
          login
          # name
        }
      }
      pipelineIssue(workspaceId: $workspaceId) {
        id
        pipeline {
          id
          name
        }
      }
      blockingIssues {
        nodes {
          id
          number
        }
      }
      blockedIssues {
        nodes {
          id
          number
        }
      }
      sprints {
        nodes {
          id
          name
        }
      }
      estimate {
        value
      }
    }
  }
`);

export const getSimpleIssueByNumberQueryDocument = graphql(`
  query GetSimpleIssueByNumber($repositoryGhId: Int!, $issueNumber: Int!) {
    issueByInfo(issueNumber: $issueNumber, repositoryGhId: $repositoryGhId) {
      id
      number
      title
    }
  }
`);

export const getAllOrganizationsQueryDocument = graphql(`
  query GetAllOrganizations {
    viewer {
      id
      zenhubOrganizations {
        nodes {
          id
          name
          workspaces {
            nodes {
              id
              name
            }
          }
        }
      }
    }
  }
`);

export const getAllEpicsQueryDocument = graphql(`
  query GetAllEpics($workspaceId: ID!) {
    workspace(id: $workspaceId) {
      id
      epics {
        nodes {
          id
          issue {
            id
            number
            title
            closedAt
          }
        }
      }
    }
  }
`);

export const createBlockageMutationDocument = graphql(`
  mutation CreateBlockage($blockingId: ID!, $blockedId: ID!) {
    createBlockage(
      input: {
        blocking: { id: $blockingId, type: ISSUE }
        blocked: { id: $blockedId, type: ISSUE }
      }
    ) {
      blockage {
        id
      }
    }
  }
`);

export const deleteIssueDependencyMutationDocument = graphql(`
  mutation DeleteIssueDependency(
    $repositoryGhId: Int!
    $blockingIssueNumber: Int!
    $blockedIssueNumber: Int!
  ) {
    deleteIssueDependency(
      input: {
        blockingIssue: {
          repositoryGhId: $repositoryGhId
          issueNumber: $blockingIssueNumber
        }
        blockedIssue: {
          repositoryGhId: $repositoryGhId
          issueNumber: $blockedIssueNumber
        }
      }
    ) {
      issueDependency {
        id
      }
    }
  }
`);
